diff --git a/packages/runtime/src/jsc/tool_runtime.zig b/packages/runtime/src/jsc/tool_runtime.zig
index dba13953b..50d682ed0 100644
--- a/packages/runtime/src/jsc/tool_runtime.zig
+++ b/packages/runtime/src/jsc/tool_runtime.zig
@@ -27,3 +27,18 @@ pub const rejections = @import("tool_rejections.zig");
 pub const evaluate = @import("evaluate.zig");
 pub const extern_fns = @import("extern_fns.zig");
 pub const opaques = @import("opaques.zig");
+
+/// Repository commands retain their modules while creating many transient
+/// render values. Use the linked provider's collectible context for that work.
+pub fn initEngine(allocator: @import("std").mem.Allocator) !Engine {
+    if (comptime @import("build_options").use_zig_js) {
+        const provider = struct {
+            extern fn ZJSGlobalContextCreateGarbageCollected(enable_jit: bool) ?*opaques.JSContextRef;
+        };
+        return .{
+            .allocator = allocator,
+            .context = provider.ZJSGlobalContextCreateGarbageCollected(true) orelse return error.JSCInitFailed,
+        };
+    }
+    return Engine.init(allocator);
+}

fixtures.entropy-churn.mjs:
import fs from "node:fs";
if(Home.engine!=="zig-js")throw new Error("wrong engine");
const input=fs.readFileSync(process.argv[2],"utf8");let checksum=0;for(let i=0;i<8192;i++){const out=input.replace(/\x00/g,"y");if(out.length!==input.length)throw new Error("bad replacement");checksum+=out.charCodeAt((i*8191)%input.length);}
console.log("OK entropy churn",checksum);

